// Read-only adaptation of Feature Foundry prototype-v24.ts roomStateSnapshot.
// Saved descriptions are claims from the file, not verified meshes, physics or actions.
const MAX_BYTES=1024*1024,MAX_OBJECTS=500;
const rootKeys=['sourceName','imported','importMode','keepUnified','detachInteractables','autoPhysics','mascotAffordances','selectedId','stage','tableAssetId','objects'];
const rowKeys=['id','name','icon','role','physics','interactive','detachable','visible','locked','state','actions','mascot','atlasId'];
function fields(v,keys,label){if(!v||typeof v!=='object'||Array.isArray(v))throw Error(`${label} must be an object.`);for(const k of Object.keys(v))if(!keys.includes(k))throw Error(`${label} contains an unsupported field; original file retained outside this app.`);}
function string(v,label,max=1024){if(typeof v!=='string'||v.length>max||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(v))throw Error(`${label} must be bounded text.`);}
// JSON.parse alone silently accepts duplicate keys; scan bounded structure first.
function unambiguous(text){
 const tokens=text.match(/"(?:[^"\\]|\\.)*"|[{}\[\]:,]|[^\s{}\[\]:,]+/g)||[];let i=0;
 function visit(depth=0){if(depth>24)throw Error('Snapshot nesting exceeds 24 levels.');const t=tokens[i++];if(t==='{'){const keys=new Set();if(tokens[i]==='}'){i++;return;}while(i<tokens.length){const key=JSON.parse(tokens[i++]);if(keys.has(key))throw Error('Duplicate JSON keys are ambiguous and unsupported.');keys.add(key);if(tokens[i++]!==':')throw Error('Invalid JSON object.');visit(depth+1);if(tokens[i++]==='}')return;}}else if(t==='['){if(tokens[i]===']'){i++;return;}while(i<tokens.length){visit(depth+1);if(tokens[i++]===']')return;}}}
 visit();
}
export function parseSemanticRoom(bytes){
 if(!(bytes instanceof Uint8Array)||bytes.byteLength===0||bytes.byteLength>MAX_BYTES)throw Error('Choose a nonempty UTF-8 JSON snapshot up to 1 MiB.');
 let value;try{const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);value=JSON.parse(text);unambiguous(text);}catch(error){throw Error('Snapshot must contain valid unambiguous UTF-8 JSON: '+error.message);}
 fields(value,rootKeys,'Room');for(const k of rootKeys)if(!Object.hasOwn(value,k))throw Error(`Missing room field: ${k}.`);
 for(const k of ['sourceName','importMode','stage'])string(value[k],k);
 for(const k of ['imported','keepUnified','detachInteractables','autoPhysics','mascotAffordances'])if(typeof value[k]!=='boolean')throw Error(`${k} must be boolean.`);
 for(const k of ['selectedId','tableAssetId'])if(value[k]!==null)string(value[k],k,256);
 if(!Array.isArray(value.objects)||value.objects.length>MAX_OBJECTS)throw Error('Room objects must be an array of at most 500 records.');
 const ids=new Set();for(const row of value.objects){fields(row,rowKeys,'Object');for(const k of rowKeys.filter(k=>k!=='atlasId'))if(!Object.hasOwn(row,k))throw Error(`Missing object field: ${k}.`);for(const k of ['id','name','icon','role','physics','state','mascot'])string(row[k],k,k==='id'?256:1024);if(!row.id||ids.has(row.id))throw Error('Object IDs must be nonempty and unique.');ids.add(row.id);if(Object.hasOwn(row,'atlasId'))string(row.atlasId,'atlasId',256);for(const k of ['interactive','detachable','visible','locked'])if(typeof row[k]!=='boolean')throw Error(`${k} must be boolean.`);if(!Array.isArray(row.actions)||row.actions.length>64)throw Error('Object actions must contain at most 64 text labels.');row.actions.forEach(x=>string(x,'Action',256));}
 if(value.selectedId!==null&&!ids.has(value.selectedId))throw Error('Selected object does not exist in this snapshot.');return value;
}
export function attachSemanticRoom({host,signal,createURL=blob=>URL.createObjectURL(blob),revokeURL=url=>URL.revokeObjectURL(url)}){
 const doc=host.ownerDocument;let generation=0,disposed=false,active=null,url=null;
 host.innerHTML='<h2>Original room metadata explorer</h2><p>Explicit local ff-room-semantic-state JSON only. Read-only, session-only: no upload, storage, mesh import, physics generation or action execution. Descriptions below are unverified source metadata, not working capabilities.</p><label>Choose room snapshot (1 MiB maximum) <input type="file" accept=".json,application/json" data-semantic-file></label><button data-semantic-close disabled>Close and forget snapshot</button><a data-semantic-export hidden download="original-room-semantic-state.json">Export exact original bytes</a><p role="status" data-semantic-status>No snapshot selected.</p><div data-semantic-summary></div><label>Inspect saved object <select data-semantic-select disabled></select></label><dl data-semantic-details></dl>';
 const one=q=>host.querySelector(q),input=one('[data-semantic-file]'),close=one('[data-semantic-close]'),link=one('[data-semantic-export]'),status=one('[data-semantic-status]'),summary=one('[data-semantic-summary]'),select=one('[data-semantic-select]'),details=one('[data-semantic-details]');
 function revoke(){if(url){revokeURL(url);url=null;}link.removeAttribute('href');link.hidden=true;}
 function detail(){details.replaceChildren();const row=active?.value.objects.find(r=>r.id===select.value);if(!row)return;for(const [key,value] of Object.entries(row)){const dt=doc.createElement('dt'),dd=doc.createElement('dd');dt.textContent=key;dd.textContent=Array.isArray(value)?value.join(', '):String(value);details.append(dt,dd);}}
 function render(){const v=active.value;summary.replaceChildren();const warning=doc.createElement('p');warning.textContent='Recorded root metadata. Saved flags and descriptions are not validation of an actual room.';summary.append(warning);const list=doc.createElement('dl');for(const key of rootKeys.filter(k=>k!=='objects')){const dt=doc.createElement('dt'),dd=doc.createElement('dd');dt.textContent=key;dd.textContent=String(v[key]);list.append(dt,dd);}summary.append(list);select.replaceChildren();for(const row of v.objects){const option=doc.createElement('option');option.value=row.id;option.textContent=row.name;select.append(option);}select.value=v.selectedId||v.objects[0]?.id||'';select.disabled=!v.objects.length;close.disabled=false;detail();}
 async function choose(){if(disposed)return;const file=input.files?.[0];input.value='';if(!file)return;const token=++generation;if(!Number.isFinite(file.size)||file.size<=0||file.size>MAX_BYTES){status.textContent='Rejected: choose a nonempty snapshot up to 1 MiB. Previous snapshot retained.';return;}close.disabled=false;status.textContent='Reading selected local snapshot…';try{const bytes=new Uint8Array(await file.arrayBuffer());if(disposed||signal?.aborted||token!==generation)return;const value=parseSemanticRoom(bytes);const nextURL=createURL(new Blob([bytes],{type:'application/json'}));try{revoke();}catch{try{revokeURL(nextURL);}catch{}throw Error('Export cleanup failed; export availability is unverified.');}active={value};url=nextURL;link.href=url;link.hidden=false;render();status.textContent='Snapshot inspected locally. Exact original bytes available for export; no migration or scene modification performed.';}catch(error){if(!disposed&&token===generation)status.textContent=`Rejected: ${error.message} Previous snapshot metadata retained.`;}}
 function clear(){generation++;active=null;try{revoke();status.textContent='Snapshot closed; session export released.';}catch{link.removeAttribute('href');link.hidden=true;status.textContent='Snapshot closed; export cleanup failed.';}summary.replaceChildren();details.replaceChildren();select.replaceChildren();select.disabled=true;close.disabled=true;input.value='';}
 function dispose(){if(disposed)return;disposed=true;clear();input.removeEventListener('change',choose);select.removeEventListener('change',detail);close.removeEventListener('click',clear);signal?.removeEventListener('abort',dispose);host.replaceChildren();}
 input.addEventListener('change',choose);select.addEventListener('change',detail);close.addEventListener('click',clear);signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return {dispose};
}
